function urlSearchUser(userName, page, full) {
    if (!page) page = 1
    const fullUrl = full ? "s_usr_full": "s_usr"
    return `https://www.pixiv.net/ajax/search/users?nick=${userName}&s_mode=${fullUrl}&i=1&p=${page}&lang=zh`
