} else if(result.includes('mp3')){
  // 获取MP3直链
    let mp3Url = java.getString('audio@src');

    // 构建播放页面
    b64 = java['base64Encode'](`
        <html>
        <head>
            <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
            <title>{{book.name}}</title>
            <style>
                body {
                    margin: 0;
                    padding: 0;
                    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                    background: #f5f5f5;
                    color: #333;
                }
                .header {
                    padding: 15px;
                    background: linear-gradient(135deg, #6e48aa, #9d50bb);
                    color: white;
                    text-align: center;
                    font-size: 1.2em;
                    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
                }
                .audio-container {
                    width: 100%;
                    padding: 20px;
                    background: white;
                    margin-top: 10px;
                }
                audio {
                    width: 100%;
                }
                .info-panel {
                    padding: 15px;
