                }
                .cover-img {
                    width: 100%;
                    max-height: 300px;
                    object-fit: contain;
                    margin-bottom: 15px;
                }
            </style>
        </head>
        <body>
            <div class="header">{{book.name}}</div>
            <div class="audio-container">
                <img src="{{book.coverUrl}}" class="cover-img" onerror="this.style.display='none'">
                <audio controls autoplay>
                    <source src="${mp3Url}" type="audio/mpeg">
                    您的浏览器不支持音频元素
                </audio>
            </div>
            <div class="info-panel">
                <div class="info-item">
                    <span class="info-label">👤 作者：</span>{{book.author}}
                </div>
