                </div>
                <div class="info-item">
                    <span class="info-label">📝 简介：</span>{{book.intro}}
                </div>
            </div>
        </body>
        </html>
    `);

    // 在浏览器中打开
    dataUrl = 'data:text/html;base64,' + b64;
    java['startBrowser'](dataUrl, '{{book.name}}');
    java['toast']('音频加载中...');

    // 返回结果
