   }
   try {
     java.startBrowserAwait(url, "登录")
   } catch (e) {
     java.toast(e)
   }
   cookies = cookie.getCookie(url)
   if (!cookies || cookies == "") {
     java.toast("登录失败！")
     return false
   }
   java.toast("登录成功！")
   return true
}

