    	 return headers;
}

function leng(str) {
	let length = 0;
	const fuhao = ',.?!:;()[]"';
	const fuhao2 = '📘';
	for (char of str) {
		if (fuhao.includes(char) ) length += 0.5;
		else if (fuhao2.includes(char) ) length += 2;
		else length += 1;
		}
		return length;
}

